class Solution:
    def validTicTacToe(self, board):
        target = tuple(board)
        def winner(s):
            lines = [s[0], s[1], s[2],
                     ''.join(s[i][j] for i in range(3)) for j in range(3),
                     ''.join(s[i][i] for i in range(3)),
                     ''.join(s[i][2-i] for i in range(3))]
            for L in lines:
                if L == 'XXX': return 'X'
                if L == 'OOO': return 'O'
            return None
        from functools import lru_cache
        seen = set()
        def dfs(state, turn):
            if state == target: return True
            if state in seen or winner(state) or ' ' not in ''.join(state): return False
            seen.add(state)
            for i in range(3):
                row = list(state[i])
                for j in range(3):
                    if row[j] == ' ':
                        row[j] = turn
                        nxt = list(state); nxt[i] = ''.join(row)
                        if dfs(tuple(nxt), 'O' if turn == 'X' else 'X'): return True
                        row[j] = ' '
            return False
        return dfs(('   ',)*3, 'X')

