class Solution {
public:
    string winner(vector<string>& s){
        for(int i=0;i<3;i++){
            if(s[i][0]!=' '&&s[i][0]==s[i][1]&&s[i][1]==s[i][2]) return string(1,s[i][0]);
            if(s[0][i]!=' '&&s[0][i]==s[1][i]&&s[1][i]==s[2][i]) return string(1,s[0][i]);
        }
        if(s[0][0]!=' '&&s[0][0]==s[1][1]&&s[1][1]==s[2][2]) return string(1,s[0][0]);
        if(s[0][2]!=' '&&s[0][2]==s[1][1]&&s[1][1]==s[2][0]) return string(1,s[0][2]);
        return "";
    }
    bool dfs(vector<string>& s, vector<string>& t, char turn){
        if(s==t) return true;
        if(!winner(s).empty()) return false;
        for(int i=0;i<3;i++)for(int j=0;j<3;j++){
            if(s[i][j]==' '){
                s[i][j]=turn;
                bool ok=dfs(s,t,turn=='X'?'O':'X');
                s[i][j]=' ';
                if(ok) return true;
            }
        }
        return false;
    }
    bool validTicTacToe(vector<string>& board){
        vector<string> s(3,string(3,' '));
        return dfs(s,board,'X');
    }
};

