class Solution {
    private String winner(char[][] s){
        for(int i=0;i<3;i++){
            if(s[i][0]!=' '&&s[i][0]==s[i][1]&&s[i][1]==s[i][2]) return ""+s[i][0];
            if(s[0][i]!=' '&&s[0][i]==s[1][i]&&s[1][i]==s[2][i]) return ""+s[0][i];
        }
        if(s[0][0]!=' '&&s[0][0]==s[1][1]&&s[1][1]==s[2][2]) return ""+s[0][0];
        if(s[0][2]!=' '&&s[0][2]==s[1][1]&&s[1][1]==s[2][0]) return ""+s[0][2];
        return "";
    }
    private boolean dfs(char[][] s, char[][] t, char turn){
        if(java.util.Arrays.deepEquals(s,t)) return true;
        if(!winner(s).isEmpty()) return false;
        for(int i=0;i<3;i++)for(int j=0;j<3;j++){
            if(s[i][j]==' '){
                s[i][j]=turn;
                boolean ok=dfs(s,t,turn=='X'?'O':'X');
                s[i][j]=' ';
                if(ok) return true;
            }
        }
        return false;
    }
    public boolean validTicTacToe(String[] board){
        char[][] s=new char[3][3];
        char[][] t=new char[3][3];
        for(int i=0;i<3;i++){ s[i]=new char[]{' ',' ',' '}; t[i]=board[i].toCharArray(); }
        return dfs(s,t,'X');
    }
}

