class Solution {
    bool wins(vector<string>& b, char p){
        for(int i=0;i<3;i++){
            bool r=true,c=true;
            for(int j=0;j<3;j++){ r&=b[i][j]==p; c&=b[j][i]==p; }
            if(r||c) return true;
        }
        bool d1=true,d2=true;
        for(int i=0;i<3;i++){ d1&=b[i][i]==p; d2&=b[i][2-i]==p; }
        return d1||d2;
    }
public:
    bool validTicTacToe(vector<string>& board){
        int cx=0,co=0;
        for(auto& r:board) for(char ch:r){ if(ch=='X')cx++; if(ch=='O')co++; }
        int d=cx-co;
        if(d<0||d>1) return false;
        bool wx=wins(board,'X'), wo=wins(board,'O');
        if(wx&&d!=1) return false;
        if(wo&&d!=0) return false;
        if(wx&&wo) return false;
        return true;
    }
};

